CREATE TABLE ai_analysis(analysis_id uuid PRIMARY KEY,event_id uuid NOT NULL REFERENCES financial_event(id),model_id text NOT NULL,prompt_version text NOT NULL,input_evidence_ids uuid[] NOT NULL,status text NOT NULL CHECK(status IN('RUNNING','COMPLETED','FAILED')),input_hash char(64) NOT NULL,request_started_at timestamptz NOT NULL DEFAULT clock_timestamp(),finished_at timestamptz,generated_at timestamptz,extracted_facts jsonb NOT NULL DEFAULT '[]',hypotheses jsonb NOT NULL DEFAULT '[]',uncertainties jsonb NOT NULL DEFAULT '[]',counter_evidence jsonb NOT NULL DEFAULT '[]',verification_status text NOT NULL DEFAULT 'PENDING' CHECK(verification_status='PENDING'),numeric_validation text NOT NULL DEFAULT 'NOT_RUN' CHECK(numeric_validation IN('NOT_RUN','PASS','REVIEW_REQUIRED','FAILED')),translated_title text,summary text,raw_output jsonb,error_code text);
CREATE INDEX ai_event_history ON ai_analysis(event_id,request_started_at DESC);
CREATE FUNCTION ai_evidence_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF cardinality(NEW.input_evidence_ids)=0 OR EXISTS(SELECT 1 FROM unnest(NEW.input_evidence_ids) id LEFT JOIN raw_evidence r ON r.id=id WHERE r.id IS NULL OR r.raw_content_hash<>encode(sha256(r.raw_content),'hex')) THEN RAISE EXCEPTION 'AI requires intact stored evidence'; END IF;RETURN NEW;END $$;
CREATE TRIGGER ai_input_evidence BEFORE INSERT OR UPDATE ON ai_analysis FOR EACH ROW EXECUTE FUNCTION ai_evidence_guard();
